/**
 * Unrealism, measured: the deployed room's own published lines against a transcript
 * generated by the current code with no model available (which is what the deployed room
 * spends most of the day in).
 *
 * Left in the repo root beside the probe scripts as reproducible evidence.
 */
import { readFileSync } from "node:fs";

import { advance } from "./lib/forum/advance";
import type { ChatProvider } from "./lib/forum/provider";
import { auditTurns, metricNotApplicable, realismMisses, realismScore, REALISM_TARGETS } from "./lib/forum/realism";
import { createFixture } from "./lib/forum/test-utils";
import type { TurnRecord } from "./lib/forum/types";

const dead: ChatProvider = {
  id: "dead",
  model: "dead/model",
  family: "dead",
  chat: async () => {
    throw new Error("429 Rate limit exceeded: free-models-per-day");
  },
};

function report(label: string, turns: readonly TurnRecord[], roster: readonly string[]): void {
  // Without the roster the audit cannot tell a member from a visitor, so `silenceRate` falls
  // back to "not applicable" (reported as 100%) and the room's silences beside *people* go
  // unmeasured. Every line of evidence below is worth less than the roster it was read with.
  const audit = auditTurns(turns, roster);
  const score = realismScore(audit);
  console.log(`\n=== ${label} ===`);
  console.log(`  published persona lines: ${audit.messages}`);  for (const target of REALISM_TARGETS) {
    const value = audit[target.metric];
    // The same rule the score uses, so the display cannot contradict it: a metric with
    // nothing to measure is neither a pass nor a miss.
    const na = metricNotApplicable(target, audit);
    const failed =
      !na &&
      ((target.max !== undefined && value > target.max) || (target.min !== undefined && value < target.min));
    console.log(
      `  ${na ? " n/a" : failed ? "MISS" : " ok "} ${target.metric.padEnd(20)} ${String((value * 100).toFixed(1)).padStart(6)}%  (${target.why})`,
    );
  }
  console.log(`  realism score: ${score}/100`);
  const misses = realismMisses(audit);
  if (misses.length > 0) console.log(`  misses: ${misses.map((m) => m.metric).join(", ")}`);
}

async function deployed(): Promise<{ turns: TurnRecord[]; roster: string[] }> {
  const { Client } = await import("pg");
  const url = readFileSync("/tmp/.forum-db-url", "utf8").trim();
  const client = new Client({ connectionString: url, ssl: { rejectUnauthorized: false } });
  await client.connect();
  const rows = await client.query("select record from forum_turns order by seq desc limit 400");
  await client.end();
  return {
    turns: rows.rows.map((row) => row.record as TurnRecord).reverse(),
    roster: await rosterIds(),
  };
}

/** The members of the room, by id — the same roster on both sides of the comparison. */
async function rosterIds(): Promise<string[]> {
  const { FileStore } = await import("./lib/forum/store");
  const personas = await new FileStore(`${process.cwd()}/data/forum`).readPersonas();
  return personas.map((persona) => persona.id);
}

async function generated(): Promise<{ turns: TurnRecord[]; roster: string[] }> {
  const { FileStore } = await import("./lib/forum/store");
  const real = new FileStore(`${process.cwd()}/data/forum`);
  const [personas, config, topics, world] = await Promise.all([
    real.readPersonas(),
    real.readConfig(),
    real.readTopics(),
    real.readWorld(),
  ]);
  const fixture = await createFixture({ personas, config, topics, world });
  try {
    const questions = [
      "yo, just joined. what is this place 😅",
      "how do i put money in btw? cant find the deposit thing",
      "so how does the trading actually work, does the ai do it all?",
      "can i set a loss limit on it",
      "am i gonna lose everything",
      "everyone in here seems to know each other lol. who talks the most?",
      "what's the read on gold into the close?",
      "is this a real trading room or is it the app's own chat?",
      "how do i take money back out",
      "what does it cost",
    ];
    let now = 1_800_000_000_000;
    let qi = 0;
    for (let step = 0; step < 320; step += 1) {
      now += 45_000;
      // A person speaks every 17th turn, so the run is mostly the room's own chatter with a
      // visitor landing in it now and then, the way the live room actually runs.
      if (step % 17 === 0) {
        const topic = topics[0]!;
        await fixture.store.appendHumanMessage({
          text: questions[qi % questions.length]!,
          sender: "human",
          t: now,
          topicId: topic.id,
        });
        qi += 1;
      }
      await advance(fixture.store, {
        now,
        driver: "audit",
        voiceProvider: dead,
        peekInjections: async () => null,
      });
    }
    return {
      turns: await fixture.store.readTurns(Number.POSITIVE_INFINITY),
      roster: personas.map((persona) => persona.id),
    };
  } finally {
    await fixture.cleanup();
  }
}

(async () => {
  const roster = await rosterIds();
  try {
    const live = await deployed();
    report("DEPLOYED ROOM (last 400 turns, mostly the old fallback bank)", live.turns, roster);
  } catch (error) {
    console.error("deployed read failed:", error instanceof Error ? error.message : error);
  }
  const fresh = await generated();
  report("NEW CODE, no model available (what a visitor reads under quota pressure)", fresh.turns, fresh.roster);
})().catch((error) => {
  console.error("AUDIT_FAIL:", error);
  process.exit(1);
});
